class Savings:
    def __init__(self, balance):
        self.balance = balance

    def withdraw(self, amount):
        self.balance -= amount
        return self.balance

class Guarded(Savings):
    def withdraw(self, amount):
        if amount > self.balance:
            return "declined"
        return super().withdraw(amount)

g = Guarded(100)
print(g.withdraw(150), g.balance)

class Character:
    def __init__(self, name, health=100):
        self.name = name
        self.health = health

    def take_damage(self, amount):
        self.health -= amount

class Warrior(Character):
    def __init__(self, name):
        super().__init__(name, 120)
        self.armor = 5

    def take_damage(self, amount):
        super().take_damage(max(0, amount - self.armor))

w = Warrior("Ada")
w.take_damage(3)
w.take_damage(20)
print(w.health)
